import type { DiagramEdge, DiagramNode, DiagramSpecV010 } from "./contracts.js";
export type DiagramCommand={type:"add-node";node:DiagramNode}|{type:"move-node";id:string;x:number;y:number}|{type:"remove-node";id:string}|{type:"add-edge";edge:DiagramEdge}|{type:"remove-edge";id:string};
export interface PositionedNode extends DiagramNode { x?:number;y?:number; }
export interface EditableDiagram extends Omit<DiagramSpecV010,"nodes"> { nodes:PositionedNode[]; }
export function applyDiagramCommand(d:EditableDiagram,c:DiagramCommand):EditableDiagram { let nodes=d.nodes.map(n=>({...n})),edges=d.edges.map(e=>({...e}));switch(c.type){case"add-node":if(!nodes.some(n=>n.id===c.node.id))nodes.push({...c.node});break;case"move-node":{const n=nodes.find(n=>n.id===c.id);if(n){n.x=c.x;n.y=c.y;}}break;case"remove-node":nodes=nodes.filter(n=>n.id!==c.id);edges=edges.filter(e=>e.source!==c.id&&e.target!==c.id);break;case"add-edge":if(nodes.some(n=>n.id===c.edge.source)&&nodes.some(n=>n.id===c.edge.target)&&!edges.some(e=>e.id===c.edge.id))edges.push(c.edge);break;case"remove-edge":edges=edges.filter(e=>e.id!==c.id);break;}return {...d,nodes,edges};}
export function simpleFlowLayout(d:EditableDiagram):EditableDiagram { const indeg=new Map(d.nodes.map(n=>[n.id,0]));for(const e of d.edges)indeg.set(e.target,(indeg.get(e.target)??0)+1);const q=d.nodes.filter(n=>(indeg.get(n.id)??0)===0).map(n=>n.id),level=new Map<string,number>();q.forEach(id=>level.set(id,0));for(let i=0;i<q.length;i++){const id=q[i]!;for(const e of d.edges.filter(e=>e.source===id)){level.set(e.target,Math.max(level.get(e.target)??0,(level.get(id)??0)+1));indeg.set(e.target,(indeg.get(e.target)??1)-1);if(indeg.get(e.target)===0)q.push(e.target);}}const counters=new Map<number,number>();return {...d,nodes:d.nodes.map(n=>{const l=level.get(n.id)??0,c=counters.get(l)??0;counters.set(l,c+1);return {...n,x:80+l*220,y:70+c*110};})};}
